// Generates src/runner/generated/ (run: `pnpm generate:runner` in this folder, or `node scripts/generate-runner.mjs`):
// - mvs-types.ts and svs-types.ts: the typings Monaco gets for MVS and SVS snippets, each as one .d.ts string
//   (_spec/README.md decision 3). The published declarations of @molstar/mvs-builder (or @molstar/seq-core's builder) and
//   what they import become `declare module '<specifier>' { ... }` blocks of one script file, and the globals the snippet
//   sees (`builder`, `molql()`, `pymol()`, `seq`, `asset()`, ...) are declared on top of them.
// - runtime.ts: the iframe's runtime (src/runner/runtime/entry.ts with both builders), bundled by Vite, as a string.

import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, realpathSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, sep } from 'node:path';
import ts from '@typescript/typescript6';
import { build, defaultClientConditions } from 'vite';

const root = join(import.meta.dirname, '..');
const repo = join(root, '..', '..');
const out = join(root, 'src', 'runner', 'generated');
const builderDir = realpathSync(join(root, 'node_modules', '@molstar', 'mvs-builder'));
const seqDir = realpathSync(join(root, 'node_modules', '@molstar', 'seq-core'));

const HEADER = `/**
 * Copyright (c) 2026 mol* contributors, licensed under MIT, See LICENSE file for more info.
 *
 * Developed in collaboration with Anyfold <https://anyfold.ai/>
 *
 * @author David Sehnal <david.sehnal@gmail.com>
 *
 * Generated by scripts/generate-runner.mjs. Do not edit.
 */
`;

/** A builder's declarations are emitted by its build (\`tsc -b\`); do that when \`lib/\` is missing. */
function ensureDeclarations(dir, file) {
  if (existsSync(join(dir, 'lib', file))) return;
  console.log(`Building ${dir} (lib/ is missing).`);
  execFileSync('pnpm', ['exec', 'tsc', '-b', dir], { cwd: repo, stdio: 'inherit' });
}

/** The globals of every snippet kind. */
const COMMON_GLOBALS = `
/**
 * The address of a data file of this page (the files of public/data), for color_from_uri and the like:
 * asset('p53-hotspots.json'). The code runs without a page address of its own, so this is how to name them.
 */
declare function asset(name: string): string;
declare const console: { log(...args: unknown[]): void; warn(...args: unknown[]): void; error(...args: unknown[]): void };
`;

/** What the MVS typings start from; the globals below refer to these modules. */
const MVS_ENTRY = `
export type { Root } from '@molstar/mvs-builder/tree/mvs/mvs-builder';
export type { SnapshotMetadata } from '@molstar/mvs-builder/mvs-data';
export { MolScriptBuilder } from '@molstar/mvs-builder/molql';
`;

/** Packages outside the workspace whose declarations are bundled; all others are declared as \`any\` modules. */
const BUNDLED_EXTERNAL = new Set(['io-ts']);

const BUILDER = `import('@molstar/mvs-builder/tree/mvs/mvs-builder').Root`;

/** The globals of an MVS snippet (runtime/core.ts provides them) and readable names for the builder's types. */
const MVS_GLOBALS = `
/** The MVS builder: describes the scene. Start with \`builder.download(...)\`. */
declare const builder: ${BUILDER};
/**
 * A selection as text, as a selector: \`{ molql }\`, usable wherever the builder takes a selector (components, colors).
 * PyMOL by default, e.g. \`molql('byres polymer within 5 of resn STI')\`; VMD, Jmol and MolScript text also work.
 */
declare function molql(text: string, language?: 'pymol' | 'vmd' | 'jmol' | 'mol-script'): { molql: unknown };
/**
 * A PyMOL selection as a selector, the shorthand for molql(text, 'pymol'): pymol('byres (chain A within 5 of resn STI)').
 * The text is read at once, so a mistake in it is reported at this line.
 */
declare function pymol(text: string): { molql: unknown };
/** A structure file, and the chain of it that is meant. */
interface TmAlignFile {
  /** Where to download it from (http or https). */
  url: string;
  format: 'bcif' | 'mmcif';
  /** The chain id of the file (auth_asym_id). Default: the first polymer chain. */
  chain?: string;
}
interface TmAlignResult {
  /** 4x4, column major: the mobile chain onto the reference. Give it to a transform: .transform({ matrix: fit.matrix }). */
  matrix: number[];
  /** Normalised by the reference chain: 1 is identical, above 0.5 the same fold. */
  tmScore: number;
  /** Over the aligned residues, in Angstrom. */
  rmsd: number;
  alignedLength: number;
}
/**
 * Superposes a chain of one structure file onto a chain of another with TM-align (it needs no sequence match), and
 * resolves to the matrix that moves the mobile structure onto the reference. The page downloads the files and does the
 * work, which may take a few seconds (up to a minute is allowed); put await in front of it.
 */
declare function tmAlign(input: { reference: TmAlignFile; mobile: TmAlignFile }): Promise<TmAlignResult>;
/** Mol*'s MolScript builder, for selections that text cannot say: \`{ molql: MolScriptBuilder.struct... }\`. */
declare const MolScriptBuilder: typeof import('@molstar/mvs-builder/molql').MolScriptBuilder;
/**
 * Starts one more state of a multi-state MVS (a slideshow of views) and returns its builder. Use it for every state
 * (then \`builder\` is not used), or not at all.
 */
declare function snapshot(metadata?: import('@molstar/mvs-builder/mvs-data').SnapshotMetadata): ${BUILDER};
${COMMON_GLOBALS}

/** The MVS builder: \`builder\` in a snippet. */
type MVSBuilder = ${BUILDER};
type MVSStructure = ReturnType<ReturnType<ReturnType<MVSBuilder['download']>['parse']>['modelStructure']>;
type MVSComponent = ReturnType<MVSStructure['component']>;
type MVSRepresentation = ReturnType<MVSComponent['representation']>;
type MVSPrimitives = ReturnType<MVSStructure['primitives']>;
/** What a component selects: 'polymer', 'ligand', ... , one expression, a list of expressions, or \`molql(...)\`. */
type MVSSelector = NonNullable<NonNullable<Parameters<MVSStructure['component']>[0]>['selector']>;
/** One selection expression, e.g. { label_asym_id: 'A', beg_auth_seq_id: 10, end_auth_seq_id: 20 }. */
type MVSExpression = Extract<MVSSelector, readonly unknown[]>[number];
/** A color: '#rrggbb' or a named color. */
type MVSColor = Parameters<MVSRepresentation['color']>[0]['color'];
/** A position for primitives: a point, or an expression. */
type MVSPosition = Parameters<MVSPrimitives['tube']>[0]['start'];
`;

/** What the SVS typings start from. */
const SVS_ENTRY = `
export type { SeqViewSpecBuilder } from '@molstar/seq-core/builder';
`;

/** The globals of an SVS snippet (runtime/core.ts provides them). */
const SVS_GLOBALS = `
/**
 * The SeqViewSpec builder: describes the sequence view. Start with seq.data (the structure, the annotations) and
 * seq.view (the section, its tracks).
 */
declare const seq: import('@molstar/seq-core/builder').SeqViewSpecBuilder;
${COMMON_GLOBALS}
`;

/** A string module (a template literal), so Monaco and the tests get the text without a file read. */
function asStringModule(name, doc, text) {
  const escaped = text.replaceAll('\\', '\\\\').replaceAll('`', '\\`').replaceAll('${', '\\${');
  return `${HEADER}\n/** ${doc} */\nexport const ${name}: string = \`${escaped}\`;\n`;
}

// --- Typings ------------------------------------------------------------------------------------------------------

function packageOf(file) {
  let dir = dirname(file);
  while (!existsSync(join(dir, 'package.json'))) {
    const up = dirname(dir);
    if (up === dir) throw new Error(`No package.json above ${file}.`);
    dir = up;
  }
  return { dir, name: JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8')).name };
}

/** The module specifier a declaration file is bundled under: how a snippet's world would import it. */
function moduleName(file) {
  const { dir, name } = packageOf(file);
  const rel = relative(dir, file)
    .split(sep)
    .join('/')
    .replace(/\.d\.ts$/, '');
  if (file.includes(`${sep}node_modules${sep}`)) return rel === 'lib/index' ? name : `${name}/${rel}`;
  return `${name}/${rel.replace(/^lib\//, '')}`.replace(/\/index$/, '');
}

function isBundled(file) {
  if (!file.endsWith('.d.ts')) return false;
  if (!file.includes(`${sep}node_modules${sep}`)) return true;
  return BUNDLED_EXTERNAL.has(packageOf(file).name);
}

/** One typings module: the declarations under \`entry\` (resolved from \`dir\`), then \`globals\`. */
function typings({ dir, probe, entry: entryText, globals, file, name, doc, intro }) {
  ensureDeclarations(dir, probe);
  const options = {
    module: ts.ModuleKind.NodeNext,
    moduleResolution: ts.ModuleResolutionKind.NodeNext,
    target: ts.ScriptTarget.ES2022,
    noEmit: true,
    skipLibCheck: true,
    types: [],
  };
  const entry = join(dir, '__runner-entry.d.ts');
  const host = ts.createCompilerHost(options);
  const { getSourceFile, fileExists, readFile } = host;
  host.getSourceFile = (name, ...rest) =>
    name === entry
      ? ts.createSourceFile(name, entryText, ts.ScriptTarget.ES2022, true)
      : getSourceFile.call(host, name, ...rest);
  host.fileExists = (name) => name === entry || fileExists.call(host, name);
  host.readFile = (name) => (name === entry ? entryText : readFile.call(host, name));
  const program = ts.createProgram([entry], options, host);

  const files = program.getSourceFiles().filter((f) => f.fileName !== entry && isBundled(f.fileName));
  const names = new Map(files.map((f) => [f.fileName, moduleName(f.fileName)]));
  const stubs = new Set();

  const rewrite = (sf) => {
    const edits = [];
    const specifier = (literal) => {
      const resolved = ts.resolveModuleName(literal.text, sf.fileName, options, host).resolvedModule?.resolvedFileName;
      const target = resolved && names.get(resolved);
      if (target) edits.push([literal.getStart(sf), literal.end, `'${target}'`]);
      else if (literal.text.startsWith('.')) throw new Error(`${sf.fileName}: ${literal.text} is not bundled.`);
      else stubs.add(literal.text);
    };
    const visit = (node) => {
      if ((ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) && node.moduleSpecifier) {
        specifier(node.moduleSpecifier);
      } else if (ts.isImportTypeNode(node) && ts.isLiteralTypeNode(node.argument)) {
        specifier(node.argument.literal);
      } else if (ts.isModuleDeclaration(node) && ts.isStringLiteral(node.name)) {
        // Module augmentations cannot sit inside a module block, and snippets never need them.
        edits.push([node.getStart(sf), node.end, '']);
        return;
      }
      ts.forEachChild(node, visit);
    };
    visit(sf);
    // Inside `declare module { }` everything is ambient already: no `declare` modifiers.
    for (const statement of sf.statements) {
      const modifier =
        ts.canHaveModifiers(statement) &&
        ts.getModifiers(statement)?.find((m) => m.kind === ts.SyntaxKind.DeclareKeyword);
      if (modifier) edits.push([modifier.getStart(sf), modifier.end + 1, '']);
    }
    let text = sf.text;
    for (const [start, end, replacement] of edits.sort((a, b) => b[0] - a[0])) {
      text = text.slice(0, start) + replacement + text.slice(end);
    }
    return text
      .replace(/^\/\/# sourceMappingURL=.*$/gm, '')
      .replace(/^\/\/\/ <reference.*$/gm, '')
      .trimEnd();
  };

  const blocks = files.map((sf) => {
    if (!ts.isExternalModule(sf)) throw new Error(`${sf.fileName} is not a module.`);
    return `declare module '${names.get(sf.fileName)}' {\n${rewrite(sf)}\n}`;
  });
  const shorthand = [...stubs].sort().map((name) => `declare module '${name}';`);
  const text = [intro, ...shorthand, ...blocks, globals].join('\n');
  writeFileSync(join(out, `${file}.ts`), asStringModule(name, doc, text));
  console.log(`${file}.ts: ${files.length} modules, ${(text.length / 1024).toFixed(0)} KB`);
}

// --- Runtime ------------------------------------------------------------------------------------------------------

async function runtime() {
  const result = await build({
    root,
    configFile: false,
    logLevel: 'warn',
    resolve: { conditions: ['molstar-src', ...defaultClientConditions] },
    define: { 'process.env.NODE_ENV': '"production"' },
    build: {
      write: false,
      minify: true,
      target: 'es2022',
      lib: { entry: join(root, 'src', 'runner', 'runtime', 'entry.ts'), formats: ['iife'], name: 'MvsRunnerRuntime' },
    },
  });
  const outputs = (Array.isArray(result) ? result : [result]).flatMap((r) => r.output);
  const chunk = outputs.find((o) => o.type === 'chunk');
  if (!chunk || outputs.length !== 1) throw new Error('The runtime must be one chunk.');
  writeFileSync(
    join(out, 'runtime.ts'),
    asStringModule('RUNTIME_JS', "The iframe's runtime: runtime/entry.ts with the MVS builder, bundled.", chunk.code),
  );
  console.log(`runtime.ts: ${(chunk.code.length / 1024).toFixed(0)} KB`);
}

mkdirSync(out, { recursive: true });
typings({
  dir: builderDir,
  probe: 'mvs-data.d.ts',
  entry: MVS_ENTRY,
  globals: MVS_GLOBALS,
  file: 'mvs-types',
  name: 'MVS_TYPES',
  doc: 'The typings for MVS snippets: Monaco gets them as an extra library.',
  intro:
    '// The declarations of @molstar/mvs-builder (and of what they import), one ambient module each, then the snippet globals.',
});
typings({
  dir: seqDir,
  probe: 'builder/index.d.ts',
  entry: SVS_ENTRY,
  globals: SVS_GLOBALS,
  file: 'svs-types',
  name: 'SVS_TYPES',
  doc: 'The typings for SeqViewSpec snippets: Monaco gets them as an extra library.',
  intro:
    "// The declarations of @molstar/seq-core's builder (and of what they import), one ambient module each, then the snippet globals.",
});
await runtime();
